using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class B3LodExport {
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B3_FullFloor/"));Directory.CreateDirectory(h+"mesh_data");var plan=JArray.Parse(File.ReadAllText(h+"lod_plan.json"));foreach(var p in plan){GlobalObjectId.TryParse((string)p["renderers"][0],out var id);var r=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as MeshRenderer;var m=r.GetComponent<MeshFilter>().sharedMesh;using(var w=new BinaryWriter(File.Create(h+"mesh_data/"+(string)p["name"]+".bin"))){var vs=m.vertices;var ns=m.normals;var uv=m.uv;w.Write(vs.Length);w.Write(m.subMeshCount);for(int i=0;i<vs.Length;i++){w.Write(vs[i].x);w.Write(vs[i].y);w.Write(vs[i].z);w.Write(ns[i].x);w.Write(ns[i].y);w.Write(ns[i].z);w.Write(uv.Length==vs.Length?uv[i].x:0);w.Write(uv.Length==vs.Length?uv[i].y:0);}for(int j=0;j<m.subMeshCount;j++){var tr=m.GetTriangles(j);w.Write(tr.Length);foreach(int n in tr)w.Write(n);}}p["materialNames"]=JArray.FromObject(r.sharedMaterials.Select(x=>x.name));p["boundsCenter"]=JArray.FromObject(new[]{m.bounds.center.x,m.bounds.center.y,m.bounds.center.z});p["boundsSize"]=JArray.FromObject(new[]{m.bounds.size.x,m.bounds.size.y,m.bounds.size.z});}File.WriteAllText(h+"lod_plan.json",plan.ToString());return new{exported=plan.Count};}
}
